const hoyISO=()=>isoDia(new Date());function masDias(iso,n){const d=new Date(iso+'T00:00:00');d.setDate(d.getDate()+n);return isoDia(d);}
function tocaHoy(ch){const st=stats[ch];return!!st&&(!st.due||st.due<=hoyISO());}
function kanjiDelLibro(){const out=new Set();book.lessons.forEach(l=>lessonKanji(l).forEach(ch=>out.add(ch)));return[...out];}
function paraRepasar(){return kanjiDelLibro().filter(tocaHoy);}
function renderSrs(){const n=paraRepasar().length;const el=document.getElementById('v-srs');if(!el)return;el.textContent=n;el.className='val '+(n?'no':'yes');document.getElementById('btn-srs').title=n?n+' kanji tocan hoy. Abre el juego con ellos.':'Nada que repasar hoy: todo está al día.';}
