function recordStat(ch,ok){if(!ch)return;const st=stats[ch]||(stats[ch]={ok:0,ko:0});ok?st.ok++:st.ko++;const caja=ok?Math.min((st.caja||0)+1,SRS_DIAS.length):0;st.caja=caja;st.due=caja?masDias(hoyISO(),SRS_DIAS[caja-1]):hoyISO();saveStats();renderSrs();}
function levelOf(ch){const st=stats[ch];if(!st)return'new';const n=st.ok+st.ko;if(n<2)return st.ko?'bad':'mid';const rate=st.ok/n;if(rate>=0.8&&n>=3)return'good';return rate>=0.5?'mid':'bad';}
let heatOn=LS.get('kj_heat')==='on';function toggleHeat(){heatOn=!heatOn;LS.set('kj_heat',heatOn?'on':'off');applyHeat();toast(heatOn?'Progreso a la vista: verde dominado, ámbar dudoso, rojo flojo':'Colores de progreso ocultos');}
