function statsSummary(){const todos=[];book.lessons.forEach(l=>lessonKanji(l).forEach(c=>todos.push(c)));let good=0,mid=0,bad=0;todos.forEach(c=>{const l=levelOf(c);if(l==='good')good++;else if(l==='mid')mid++;else if(l==='bad')bad++;});return{good,mid,bad,total:todos.length};}
