let jaVoice=null,voiceWarned=false;function pickVoice(){if(jaVoice)return jaVoice;const vs=(window.speechSynthesis&&speechSynthesis.getVoices())||[];jaVoice=vs.find(v=>/^ja(-|_|$)/i.test(v.lang))||null;return jaVoice;}
