const ES_KANJI=/[々㐀-鿿豈-﫿]/;const EXAM_POOL=10;function buildExamDeck(modo,chars){const vistos=new Set(chars);const yaPuesto=new Set();const out=[];chars.forEach(ch=>vocabOf(ch,true).forEach(v=>{const palabra=v[0];if(yaPuesto.has(palabra))return;const lectura=String(v[1]).split('/')[0].trim();const trozos=lectura.split('·').join('・').split('・').filter(Boolean);const kanjis=Array.from(palabra).filter(c=>ES_KANJI.test(c));if(!kanjis.length)return;yaPuesto.add(palabra);const base={char:ch,tipo:modo,palabra,es:v[2],lectura,kanjis,kana:trozos.join('')};if(modo==='examk'){const partes=Array.from(palabra).map(c=>{if(!ES_KANJI.test(c))return{hueco:false,v:c};if(!vistos.has(c))return{hueco:false,v:c,regalo:true,pista:KD[c]?KD[c][3].split('; ')[0]:''};return{hueco:true,v:c};});if(!partes.some(p=>p.hueco))return;out.push(Object.assign({},base,{partes,solucion:palabra,pedidos:partes.filter(p=>p.hueco).map(p=>p.v)}));}else{const soloKanji=kanjis.length===Array.from(palabra).length;const alineado=soloKanji&&trozos.length===kanjis.length;const sinVer=kanjis.filter(k=>!vistos.has(k));if(sinVer.length&&!alineado)return;const partes=trozos.map((t,i)=>{const k=alineado?kanjis[i]:null;if(k&&!vistos.has(k))return{hueco:false,v:t,regalo:true,pista:KD[k]?KD[k][3].split('; ')[0]:''};return{hueco:true,v:t};});if(!partes.some(p=>p.hueco))return;out.push(Object.assign({},base,{partes,solucion:trozos.join('・'),pedidos:alineado?kanjis.filter(k=>vistos.has(k)):kanjis}));}}));return out;}
function palabraConPistas(palabra,vistos){return Array.from(palabra).map(c=>{if(!ES_KANJI.test(c)||vistos.has(c)||!KD[c])return esc(c);return'<ruby>'+esc(c)+'<rt>'+esc(KD[c][3].split('; ')[0])+'</rt></ruby>';}).join('');}
let examSel=null;function askExam(q){const linea=document.getElementById('exam-line');const bandeja=document.getElementById('exam-pool');const vistos=new Set(G.alcance||[]);examSel=null;const qEl=document.getElementById('game-q');qEl.className='game-q exam-q';qEl.innerHTML=G.modo==='examk'?'<span class="big">'+esc(q.lectura.split('・').join('・'))+'</span>'+'<span class="es">'+esc(q.es)+'</span>':'<span class="big">'+palabraConPistas(q.palabra,vistos)+'</span>'+'<span class="es">'+esc(q.es)+'</span>';linea.innerHTML=q.partes.map((p,i)=>{if(p.hueco)return'<div class="exam-slot" data-i="'+i+'"></div>';if(p.regalo)return'<span class="exam-fix regalo">'+esc(p.v)+
(p.pista?'<i>'+esc(p.pista)+'</i>':'')+'</span>';return'<span class="exam-fix">'+esc(p.v)+'</span>';}).join('');const buenas=q.partes.filter(p=>p.hueco).map(p=>p.v);const fuente=new Set();G.pool.forEach(o=>o.partes.forEach(p=>{if(p.hueco)fuente.add(p.v);}));buenas.forEach(b=>fuente.delete(b));const senuelos=shuffle([...fuente]).slice(0,Math.max(0,EXAM_POOL-buenas.length));bandeja.innerHTML=shuffle(buenas.concat(senuelos)).map(v=>'<div class="exam-tile" draggable="true" data-v="'+esc(v)+'">'+esc(v)+'</div>').join('');}
function examPoner(hueco,ficha){if(G.answered||!hueco||!ficha)return;examVaciar(hueco);hueco.dataset.v=ficha.dataset.v;hueco.textContent=ficha.dataset.v;hueco.classList.add('lleno');ficha.classList.add('usada');hueco.dataset.ficha=[...document.querySelectorAll('.exam-tile')].indexOf(ficha);examSel=null;document.querySelectorAll('.exam-tile').forEach(t=>t.classList.remove('over'));const huecos=[...document.querySelectorAll('.exam-slot')];if(huecos.every(h=>h.dataset.v))setTimeout(checkExam,220);}
